#!/usr/bin/env python3
"""Check complete raw coverage, provenance, aggregate formulas and regenerated outputs.

--render redraws in a temporary directory and compares generated bytes.
--recompute DATASET --rs VALUE reevaluates the actual integral in a temporary
directory and compares every replicate, setting and non-source metadata field,
after translating the declared historical frequency-grid key names.
Historical source hashes may differ only by an explicitly audited compatibility entry.
--seal writes the release manifest after all notebook/PDF work is complete.
"""
import argparse
import hashlib
import json
from pathlib import Path
import subprocess
import sys
import tempfile
import runtime
if __name__ == "__main__": runtime.enter_cli()
import numpy as np
from common import ROOT, config, source_hashes, E2X, key, save, check_reference, check_source_compatibility


def settings_in_current_notation(settings):
    """Translate only historical frequency-grid names, without relaxing values.

    Both spellings in one record are ambiguous and rejected, even if their
    values happen to agree. The source dictionary and saved bytes are untouched.
    """
    current = dict(settings)
    for old, new in (('nxi', 'nnu'), ('refined_nxi', 'refined_nnu')):
        if old in current:
            if new in current:
                raise ValueError(f'Ambiguous frequency setting: both {old} and {new}')
            current[new] = current.pop(old)
    return current


def validate_records():
    cfg=config();count=0
    for dataset in ['tableI','tableII','tableIII_direct','tableIV','map','shell','grid']:
        settings=cfg[dataset]
        for rs in settings['rs']:
            for z in settings.get('zeta',[0.]):
                path=ROOT/'production/raw'/dataset/(key(rs,z)+'.json');row=json.loads(path.read_text())
                check_source_compatibility(row['metadata']['sources'])
                check_reference(path.relative_to(ROOT/'production/raw'),row)
                assert row['dataset']==dataset and row['rs']==rs,f'Wrong identity: {path}'
                if 'term_replicates_ry' in row:
                    assert row['zeta']==z
                    a=np.asarray(row['term_replicates_ry']);assert a.shape==(settings['replicates'],2)
                    mean=1000*(E2X+a.mean(axis=0).sum());se=1000*np.sqrt(a.var(axis=0,ddof=1).sum()/len(a))
                    np.testing.assert_allclose([row['mean_mry'],row['se_mry']],[mean,se],rtol=0,atol=1e-11)
                else:
                    assert settings_in_current_notation(row['settings']) == settings_in_current_notation(settings), f'Settings mismatch: {path}'
                    for k,v in row.items():
                        if 'replicates' in k:
                            a=np.asarray(v);assert a.shape[0]==settings['replicates'] and np.all(np.isfinite(a))
                count+=1
    print(f'PASS: {count} numerical records, complete configured coverage and aggregate formulas.')


def generated_files():
    return [ROOT/'data/tables.json', ROOT/'figs/data/map.dat', ROOT/'figs/data/shell.dat']+[p for folder in ['spin/generated','spin/figs','production/generated','figs']
            for p in (ROOT/folder).glob('*') if p.is_file() and
            (folder!='figs' or p.name in ['fig_shell.pdf','fig_lowdensity.pdf','fig_map.pdf','fig_residuals.pdf'])]


def release_paths():
    for p in sorted(ROOT.rglob('*')):
        if not p.is_file() or '__pycache__' in p.parts or 'build' in p.parts or '.git' in p.parts or '.venv' in p.parts or '.pytest_cache' in p.parts:continue
        if p.name=='release_manifest.json' or p.suffix in ['.log','.aux','.blg','.fls','.fdb_latexmk','.out','.pyc']:continue
        yield p


def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--render',action='store_true')
    p.add_argument('--recompute',choices=['tableI','tableII','tableIII_direct','tableIV','map','shell','grid'])
    p.add_argument('--rs',type=float);p.add_argument('--zeta',type=float);p.add_argument('--seal',action='store_true')
    p.add_argument('--manifest',action='store_true');a=p.parse_args();validate_records()
    if a.render:
        with tempfile.TemporaryDirectory(prefix='prb-redraw-') as td:
            subprocess.run([sys.executable,str(ROOT/'production/render.py'),'--output',td],check=True)
            for expected in Path(td).rglob('*'):
                if not expected.is_file():continue
                actual=ROOT/expected.relative_to(td)
                if not actual.exists() and str(expected.relative_to(td)) in {
                    'spin/generated/numbers.tex', 'spin/generated/tableI.tex',
                    'spin/generated/tableII.tex', 'spin/generated/tableIII.tex',
                    'spin/generated/tableIV.tex'}:
                    lock=json.loads((ROOT/'production/product_lock.json').read_text())['sha256']
                    assert hashlib.sha256(expected.read_bytes()).hexdigest()==lock[str(expected.relative_to(td))]
                    continue  # TeX exports live in the separate manuscript bundle.
                assert actual.exists(),f'Missing generated output: {actual}' 
                assert actual.read_bytes()==expected.read_bytes(),f'Out-of-date generated output: {actual}'
        print('PASS: all generated figure PDFs, table rows, numerical macros and CSV/JSON outputs reproduce byte for byte.')
    if a.recompute:
        if a.rs is None:p.error('--recompute requires --rs')
        with tempfile.TemporaryDirectory(prefix='prb-recompute-') as td:
            cmd=[sys.executable,str(ROOT/'production/compute.py'),'--dataset',a.recompute,'--rs',str(a.rs),'--output',td]
            if a.zeta is not None:cmd+=['--zeta',str(a.zeta)]
            subprocess.run(cmd,check=True)
            for path in Path(td).rglob('*.json'):
                old=ROOT/'production/raw'/path.relative_to(td)
                fresh=json.loads(path.read_text());historical=json.loads(old.read_text())
                check_reference(path.relative_to(td),fresh)
                check_source_compatibility(historical['metadata']['sources'])
                fresh['metadata']['sources']=historical['metadata']['sources']
                fresh['settings']=settings_in_current_notation(fresh['settings'])
                historical['settings']=settings_in_current_notation(historical['settings'])
                assert fresh==historical, f'Numerical payload/settings mismatch: {path}'
        print('PASS: recomputed numerical payload, settings and non-source metadata are identical after the declared notation-key translation; source revisions are explicitly audited.')
    if a.seal:
        hashes={str(f.relative_to(ROOT)):hashlib.sha256(f.read_bytes()).hexdigest() for f in release_paths()}
        save(ROOT/'release_manifest.json',{'sha256':hashes,'note':'Integrity of this release; excludes execution logs and TeX intermediates.'})
        print(f'SEALED: {len(hashes)} files.')
    if a.manifest:
        m=json.loads((ROOT/'release_manifest.json').read_text())
        for name,h in m['sha256'].items():assert hashlib.sha256((ROOT/name).read_bytes()).hexdigest()==h,name
        print('PASS: release manifest.')


if __name__=='__main__':main()
